"""World sprites, all generated by code and cached: karts, scenery, shadows and halos.

Karts are a small voxel model drawn with "sprite stacking" at the size and angle they
are seen, so every size is rendered at its own resolution (one world pixel stays one
pixel; nothing is upscaled). A z-buffer keeps nearer voxels on top and side faces get
a darker shade, which gives volume. Scenery is drawn procedurally at its target
height for the same reason. Images are palette indices with ``TRANSPARENT`` holes,
turned into colour-keyed surfaces when first needed.
"""

from __future__ import annotations

import math
from functools import lru_cache

import numpy as np
import pygame

from kartlab.render.palette import KART_RAMPS, TRANSPARENT, Ink, Palette
from kartlab.render.texture import BAYER4, hash_noise

KART_LENGTH = 1.8  # metres, matches the physics
VOXEL = KART_LENGTH / 32  # metres per voxel
ANGLES = 32  # kart views around the vertical axis
ELEVATIONS = (np.radians([12, 22, 35, 55, 90])).tolist()  # view elevation buckets
SCALE_MIN, SCALE_RATIO, SCALE_STEPS = 0.06, 1.12, 36  # pixels per voxel buckets
COLORKEY = (255, 0, 255)

# Kart colour slots, replaced by a ramp (dark, main, light) for each kart.
BODY_DARK, BODY, BODY_LIGHT = 250, 251, 252


@lru_cache(maxsize=1)
def kart_voxels() -> np.ndarray:
    """(z, x, y) grid of palette indices: x forward, y left, z up; TRANSPARENT is empty."""
    nz, nx, ny = 12, 32, 20
    z, x, y = np.meshgrid(
        np.arange(nz) + 0.5, np.arange(nx) + 0.5 - nx / 2, np.arange(ny) + 0.5 - ny / 2,
        indexing="ij",
    )  # fmt: skip
    v = np.full((nz, nx, ny), TRANSPARENT, dtype=np.uint8)

    def put(mask, colour):
        v[mask & (v == TRANSPARENT)] = colour

    # Driver: helmet with a dark visor, white suit.
    helmet = (x + 3.5) ** 2 + y**2 + (z - 9.6) ** 2 <= 2.7**2
    put(helmet & (x > -2.2) & (z > 8.6) & (z < 10.6), Ink.NAVY)
    put(helmet, Ink.WHITE)
    put((x > -6) & (x < -1) & (np.abs(y) < 3) & (z > 4) & (z < 8), Ink.MIST)
    put((np.abs(x - 1.5) < 1) & (np.abs(y) < 2.5) & (np.abs(z - 6) < 1), Ink.BLACK)  # wheel
    # Rear wing on two posts.
    put((x > -15.5) & (x < -12) & (np.abs(y) < 8.5) & (z > 7) & (z < 9), BODY)
    put((np.abs(x + 13.5) < 1) & (np.abs(np.abs(y) - 4) < 1) & (z > 4) & (z < 8), Ink.ASPHALT)
    # Wheels: cylinders across the kart, with a grey hub.
    for wx in (-10.0, 10.0):
        for side in (-1.0, 1.0):
            r = np.hypot(x - wx, z - 3.2)
            tyre = (r <= 3.2) & (np.abs(y - side * 8) <= 1.8)
            put(tyre & (r <= 1.2) & (np.abs(y - side * 8) > 1.2), Ink.STONE)
            put(tyre, Ink.BLACK)
    # Engine block and exhaust at the back.
    put((x > -14) & (x < -8) & (np.abs(y) < 4) & (z > 1.5) & (z < 5.5), Ink.STONE_LIGHT)
    # Cockpit, side pods and nose.
    put((x > -6) & (x < 1) & (np.abs(y) < 3.5) & (z > 3.5) & (z < 5.5), Ink.ASPHALT)
    body = (x > -9) & (x < 7) & (np.abs(y) < 7) & (z > 1.5) & (z < 4.5)
    put(body & (z > 3.5), BODY_LIGHT)
    put(body, BODY)
    nose = (
        (x >= 7)
        & (x < 15)
        & (np.abs(y) < 5.5 - (x - 7) * 0.35)
        & (z > 1)
        & (z < 3.6 - (x - 7) * 0.15)
    )
    put(nose & (z > 2.4), BODY_LIGHT)
    put(nose, BODY)
    put((x > 12.5) & (x < 16) & (np.abs(y) < 9) & (z > 0.8) & (z < 2), BODY_DARK)  # front wing
    put((x > -13) & (x < 13) & (np.abs(y) < 6) & (z > 0.8) & (z < 2), BODY_DARK)  # floor
    return v


def _darker(palette: Palette) -> np.ndarray:
    """For each index, the palette colour closest to a darker version (side faces)."""
    return palette.nearest(np.clip(palette.rgb.astype(float) * 0.7, 0, 255))


def scale_bucket(pixels_per_voxel: float) -> int:
    k = math.log(max(pixels_per_voxel, 1e-9) / SCALE_MIN) / math.log(SCALE_RATIO)
    return int(min(max(round(k), 0), SCALE_STEPS - 1))


def bucket_scale(bucket: int) -> float:
    return SCALE_MIN * SCALE_RATIO**bucket


def elevation_bucket(elevation: float) -> int:
    return int(np.argmin([abs(elevation - e) for e in ELEVATIONS]))


def render_stack(voxels: np.ndarray, angle: float, elevation: float, scale: float, shade):
    """Draw a voxel model seen at ``angle`` (0: from behind) and ``elevation`` with
    ``scale`` pixels per voxel. Returns (indices, anchor) where anchor is the pixel of
    the model's ground centre."""
    nz, nx, ny = voxels.shape
    sin_e, cos_e = math.sin(elevation), math.cos(elevation)
    radius = math.hypot(nx, ny) / 2
    width = max(int(math.ceil(2 * radius * scale)) + 2, 1)
    height = max(int(math.ceil((2 * radius * sin_e + nz * cos_e) * scale)) + 2, 1)
    ax, ay = width / 2, height - 1 - radius * sin_e * scale
    image = np.full((height, width), TRANSPARENT, dtype=np.uint8)
    depth = np.full((height, width), np.inf)
    py, px = np.mgrid[0:height, 0:width]
    sx = (px + 0.5 - ax) / scale
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    thickness = max(int(math.ceil(cos_e * scale)), 1)
    filled = voxels != TRANSPARENT
    top = filled & np.concatenate([~filled[1:], np.ones_like(filled[:1])])  # nothing above
    for z in range(nz):
        layer = voxels[z]
        if not filled[z].any():
            continue
        for k in range(thickness):
            lift = (z + k / thickness) * cos_e
            sy = (py + 0.5 - ay) / scale + lift
            b = -sy / max(sin_e, 1e-6)
            fx = -sx * sin_a + b * cos_a  # kart frame: forward
            fy = -sx * cos_a - b * sin_a  # kart frame: left
            ix = np.floor(fx + nx / 2).astype(int)
            iy = np.floor(fy + ny / 2).astype(int)
            ok = (ix >= 0) & (ix < nx) & (iy >= 0) & (iy < ny)
            colour = np.full(image.shape, TRANSPARENT, dtype=np.uint8)
            colour[ok] = layer[ix[ok], iy[ok]]
            hit = colour != TRANSPARENT
            d = b * cos_e - (z + k / thickness) * sin_e
            closer = hit & (d < depth)
            is_top = np.zeros(image.shape, dtype=bool)
            if k == 0:
                is_top[ok] = top[z][ix[ok], iy[ok]]
            side = hit & ~is_top  # side faces are darker; top faces keep their colour
            colour[side] = shade[np.minimum(colour[side], 63)]
            image[closer] = colour[closer]
            depth[closer] = d[closer]
    return image, (ax, ay)


def to_surface(indices: np.ndarray, palette_rgb: np.ndarray) -> pygame.Surface:
    rgb = np.empty((*indices.shape, 3), dtype=np.uint8)
    clear = indices == TRANSPARENT
    rgb[~clear] = palette_rgb[indices[~clear]]
    rgb[clear] = COLORKEY
    surface = pygame.surfarray.make_surface(rgb.transpose(1, 0, 2))
    surface.set_colorkey(COLORKEY)
    return surface


class SpriteBank:
    """Lazy cache of every sprite surface, per palette variant."""

    def __init__(self, palette: Palette, variant: str = "day") -> None:
        self.palette = palette
        self.set_variant(variant)
        self._shade = _darker(palette)

    def set_variant(self, variant: str) -> None:
        self.variant = variant
        self.remap = self.palette.remap(variant)
        self._karts: dict[tuple, tuple[pygame.Surface, tuple[float, float]]] = {}
        self._props: dict[tuple, tuple[pygame.Surface, tuple[float, float]]] = {}
        self._shadows: dict[int, pygame.Surface] = {}

    def kart(self, ramp: int, angle: float, elevation: float, pixels_per_voxel: float):
        """(surface, anchor) of a kart seen at ``angle`` rad (0: from behind)."""
        a = int(round(angle / (2 * math.pi) * ANGLES)) % ANGLES
        key = (ramp, a, elevation_bucket(elevation), scale_bucket(pixels_per_voxel))
        cached = self._karts.get(key)
        if cached is None:
            voxels = kart_voxels().copy()
            dark, main, light = KART_RAMPS[ramp % len(KART_RAMPS)]
            for slot, colour in ((BODY_DARK, dark), (BODY, main), (BODY_LIGHT, light)):
                voxels[voxels == slot] = colour
            image, anchor = render_stack(
                voxels, a * 2 * math.pi / ANGLES, ELEVATIONS[key[2]], bucket_scale(key[3]),
                self._shade,
            )  # fmt: skip
            image = np.where(image == TRANSPARENT, TRANSPARENT, self.remap[np.minimum(image, 63)])
            cached = (to_surface(image.astype(np.uint8), self.palette.rgb), anchor)
            self._karts[key] = cached
        return cached

    def prop(self, kind: str, height_px: float, seed: int = 0):
        """(surface, anchor) of a scenery item ``height_px`` pixels tall."""
        h = int(min(max(round(height_px), 2), 160))
        key = (kind, h, seed % 4)
        cached = self._props.get(key)
        if cached is None:
            image = PROPS[kind](h, seed % 4)
            image = np.where(image == TRANSPARENT, TRANSPARENT, self.remap[np.minimum(image, 63)])
            anchor = (image.shape[1] / 2, image.shape[0] - 1)
            cached = (to_surface(image.astype(np.uint8), self.palette.rgb), anchor)
            self._props[key] = cached
        return cached

    def shadow(self, width_px: int) -> pygame.Surface:
        """Dithered dark ellipse, for under karts."""
        w = int(min(max(width_px, 2), 120))
        surface = self._shadows.get(w)
        if surface is None:
            h = max(w // 3, 1)
            yy, xx = np.mgrid[0:h, 0:w]
            inside = ((xx + 0.5 - w / 2) / (w / 2)) ** 2 + ((yy + 0.5 - h / 2) / (h / 2)) ** 2 <= 1
            checker = (xx + yy) % 2 == 0
            image = np.full((h, w), TRANSPARENT, dtype=np.uint8)
            image[inside & checker] = self.remap[Ink.BLACK]
            surface = to_surface(image, self.palette.rgb)
            self._shadows[w] = surface
        return surface


# -- scenery, drawn at the requested height -----------------------------------------


def _canvas(h: int, aspect: float) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    w = max(int(round(h * aspect)), 1)
    yy, xx = np.mgrid[0:h, 0:w]
    return np.full((h, w), TRANSPARENT, dtype=np.uint8), (xx + 0.5) / w, (yy + 0.5) / h


def _pine(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 0.5)
    dither = BAYER4[(v * h).astype(int) % 4, (u * img.shape[1]).astype(int) % 4]
    img[(np.abs(u - 0.5) < 0.07) & (v > 0.8)] = Ink.BROWN_DARK
    for k, (top, bottom, half) in enumerate(
        ((0.0, 0.42, 0.28), (0.22, 0.65, 0.38), (0.45, 0.86, 0.48))
    ):
        inside = (v >= top) & (v <= bottom) & (np.abs(u - 0.5) <= (v - top) / (bottom - top) * half)
        lit = (u - 0.5) < -0.05 + 0.2 * (dither - 0.5)
        img[inside] = Ink.GRASS_DARK
        img[inside & lit] = Ink.GRASS if k < 2 or seed % 2 else Ink.MOSS
    return img


def _round_tree(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 0.8)
    w = img.shape[1]
    dither = BAYER4[(v * h).astype(int) % 4, (u * w).astype(int) % 4]
    img[(np.abs(u - 0.5) < 0.06) & (v > 0.55)] = Ink.BROWN
    rng = np.random.default_rng(seed + 7)
    for _ in range(5):
        cx, cy, r = rng.uniform(0.3, 0.7), rng.uniform(0.25, 0.5), rng.uniform(0.2, 0.3)
        d = np.hypot((u - cx) * 0.8 / 0.8, (v - cy) * 0.8)
        inside = d <= r
        img[inside] = Ink.GRASS_DARK
        img[inside & ((u - cx) + (v - cy) < -r * 0.3 + 0.15 * (dither - 0.5))] = Ink.GRASS
        img[inside & ((u - cx) + (v - cy) < -r * 0.9)] = Ink.LEAF_LIGHT
    return img


def _cone(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 0.75)
    inside = np.abs(u - 0.5) <= 0.1 + 0.32 * v
    img[inside] = Ink.ORANGE
    img[inside & (v > 0.35) & (v < 0.55)] = Ink.WHITE
    img[inside & (u > 0.5 + 0.12 * v)] = Ink.RED
    img[(v > 0.88) & (np.abs(u - 0.5) < 0.48)] = Ink.BLACK
    return img


def _tyres(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 1.0)
    rings = np.floor(v * 3) % 2 == 0
    img[(np.abs(u - 0.5) < 0.45)] = Ink.BLACK
    img[(np.abs(u - 0.5) < 0.45) & rings & (np.abs(u - 0.5) > 0.3)] = Ink.ASPHALT
    img[(np.abs(u - 0.5) < 0.45) & (np.abs(u - 0.5) < 0.12)] = (
        Ink.KERB_RED if seed % 2 else Ink.WHITE
    )
    return img


def _grandstand(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 2.6)
    w = img.shape[1]
    crowd_colours = np.array([Ink.WHITE, Ink.KERB_RED, Ink.SKY, Ink.YELLOW, Ink.ORANGE, Ink.PINK])
    img[(v > 0.18)] = Ink.STONE
    px, py = (u * w).astype(int), (v * h).astype(int)
    step = max(h // 10, 2)  # one row of seats every `step` pixels
    img[(v > 0.22) & (py % step == step - 1)] = Ink.STONE_LIGHT
    noise = hash_noise(px // 2, py // step, seed)
    heads = (v > 0.25) & (v < 0.85) & (py % step == step - 2) & (px % 3 != 2) & (noise < 0.8)
    img[heads] = crowd_colours[(noise[heads] * 7.4).astype(int) % len(crowd_colours)]
    img[(v > 0.85)] = Ink.ASPHALT
    img[(v <= 0.18) & (v > 0.06)] = Ink.KERB_RED
    img[(v <= 0.06)] = Ink.MIST
    img[(np.abs(u - 0.03) < 0.02) | (np.abs(u - 0.97) < 0.02)] = Ink.STONE_LIGHT
    return img


def _banner(h: int, seed: int) -> np.ndarray:
    img, u, v = _canvas(h, 0.6)
    colours = (Ink.KERB_RED, Ink.SKY, Ink.YELLOW, Ink.PURPLE)
    img[(u < 0.12) & (v > 0.02)] = Ink.STONE_LIGHT
    cloth = (u >= 0.12) & (v > 0.05) & (v < 0.55 - 0.15 * u)
    img[cloth] = colours[seed % 4]
    img[cloth & (np.floor(u * 6 + v * 4) % 2 == 0) & (v > 0.3)] = Ink.WHITE
    return img


PROPS = {
    "pine": _pine,
    "tree": _round_tree,
    "cone": _cone,
    "tyres": _tyres,
    "grandstand": _grandstand,
    "banner": _banner,
}
PROP_HEIGHTS = {  # metres
    "pine": 7.0,
    "tree": 5.5,
    "cone": 0.7,
    "tyres": 1.0,
    "grandstand": 7.0,
    "banner": 4.0,
}
